program.source:
Algoritmo Mes
  Definir mes Como Entero;
  Leer mes;
  Si mes >= 0 Y mes <= 12 Entonces
    Escribir "válido";
  Sino
    Escribir "inválido";
  FinSi
FinAlgoritmo

